<?php
namespace App\Controllers;
use App\Core\{Auth,Database,View,Request,Csrf,Response};use App\Services\{PermissionService,UserService,ActivityService};
final class AdminController{public function users():void{Auth::requireLogin();(new PermissionService)->require('System','users');View::render('admin/users',['users'=>Database::pdo()->query('SELECT u.*,r.role_name FROM users u LEFT JOIN roles r ON r.id=u.role_id ORDER BY u.id DESC')->fetchAll()]);}public function userCreate():void{Auth::requireLogin();(new PermissionService)->require('System','users');View::render('admin/user_form',['roles'=>Database::pdo()->query('SELECT * FROM roles WHERE is_active=1 ORDER BY role_name')->fetchAll()]);}public function userStore():never{Auth::requireLogin();(new PermissionService)->require('System','users');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new UserService)->create($r->all());Response::redirect(route('admin.users'));}public function userEdit($id):void{Auth::requireLogin();(new PermissionService)->require('System','users');$s=Database::pdo()->prepare('SELECT * FROM users WHERE id=?');$s->execute([(int)$id]);View::render('admin/user_form',['user'=>$s->fetch(),'roles'=>Database::pdo()->query('SELECT * FROM roles WHERE is_active=1 ORDER BY role_name')->fetchAll()]);}public function userUpdate($id):never{Auth::requireLogin();(new PermissionService)->require('System','users');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}(new UserService)->update((int)$id,$r->all());Response::redirect(route('admin.users'));}public function roles():void{Auth::requireLogin();(new PermissionService)->require('System','roles');$selected=(int)($_GET['role_id']??1);$r=Database::pdo()->prepare('SELECT * FROM role_permissions WHERE role_id=?');$r->execute([$selected]);$assigned=array_map('intval',array_column($r->fetchAll(),'permission_id'));View::render('admin/roles',['roles'=>Database::pdo()->query('SELECT * FROM roles ORDER BY id')->fetchAll(),'permissions'=>Database::pdo()->query('SELECT * FROM permissions ORDER BY module_name,permission_label')->fetchAll(),'selected'=>$selected,'assigned'=>$assigned]);}public function roleSave():never{Auth::requireLogin();(new PermissionService)->require('System','roles');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$role=(int)$r->input('role_id');$pdo=Database::pdo();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$role]);$i=$pdo->prepare('INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)');foreach((array)$r->input('permissions',[]) as $pid)$i->execute([$role,(int)$pid]);$pdo->commit();(new ActivityService)->record('ROLE_PERMISSIONS_UPDATED','System','role',$role,null,'stage_3');}catch(\Throwable $e){$pdo->rollBack();throw $e;}Response::redirect(route('admin.roles',['role_id'=>$role]));}public function integrations():void{Auth::requireLogin();View::render('admin/integrations',['integrations'=>Database::pdo()->query('SELECT * FROM integration_accounts ORDER BY id DESC')->fetchAll()]);}}
